  function conicPoint(cx,cy,rp,ra,theta,rot=0){const e=(ra-rp)/(ra+rp),p=rp*(1+e),r=p/(1+e*Math.cos(theta)),a=theta+rot;return{x:cx+r*Math.cos(a),y:cy+r*Math.sin(a)}}
