    init(){Object.assign(this,{stage:0,targetA:1.3,chaserA:3.65,transferRot:0,transfer:false,transferP:0,hold:null,distance:40,relSpeed:0,angle:16})},setup(){if(this.stage===0){this.btn=button('等待转移窗口',()=>{if(this.btn.disabled)return;this.transfer=true;this.transferP=0;this.transferRot=this.chaserA;gotoStage(1)},{primary:true,disabled:true})}else if(this.stage===1){this.btn=button('到远月点顺行点火圆化',()=>{if(this.btn.disabled)return;gotoStage(2)},{primary:true,disabled:true})}else if(this.stage===2){holdButton('按住：轻推接近',()=>this.hold='forward',()=>this.hold=null,{primary:true});holdButton('按住：反向点火减速',()=>this.hold='brake',()=>this.hold=null,{warn:true})}else{let dock;slider('接口相对角度',-20,20,this.angle,1,v=>{this.angle=v;const good=Math.abs(v)<=2;if(dock){dock.disabled=!good;dock.classList.toggle('ready',good)}return`${v>0?'+':''}${v}°`});dock=button('完成对接',()=>{if(Math.abs(this.angle)<=2)finish()},{primary:true});dock.disabled=Math.abs(this.angle)>2}},
