    init(){Object.assign(this,{stage:0,orbitA:3.5,descentRot:0,doi:false,descentP:0,hold:false,vx:1600,alt:15000,siteX:-26,throttle:38,vz:3.5,fuel:100,warnedFuel:false})},setup(){if(this.stage===0){this.btn=button('等待离轨窗口',()=>{if(this.btn.disabled)return;this.doi=true;this.descentRot=this.orbitA-Math.PI;this.fuel-=7;gotoStage(1)},{primary:true,disabled:true})}else if(this.stage===1){this.btn=button('等待动力下降起点',()=>{if(this.btn.disabled)return;gotoStage(2)},{primary:true,disabled:true})}else if(this.stage===2){holdButton('按住：主发动机制动',()=>this.hold=true,()=>this.hold=false,{primary:true})}else{button('向左侧移',()=>{this.siteX-=4;this.fuel-=.5},{warn:true});button('向右侧移',()=>{this.siteX+=4;this.fuel-=.5},{warn:true});slider('下降发动机推力',25,100,this.throttle,1,v=>{this.throttle=v;return`${v}%`})}},
